import type { Database } from "./db.ts";

/** How long a deleted task stays recoverable before it is removed for good. */
export const TRASH_RETENTION_DAYS = 30;
const DAY_MS = 24 * 60 * 60 * 1000;

export interface Task {
  id: number;
  title: string;
  created_at: string;
  updated_at: string;
  completed_at: string | null;
  deleted_at: string | null;
}

export function listTasks(db: Database): Task[] {
  return db.all("SELECT * FROM tasks WHERE deleted_at IS NULL ORDER BY id") as unknown as Task[];
}

export function createTask(db: Database, title: string): Task {
  const now = new Date().toISOString();
  const [task] = db.all(
    "INSERT INTO tasks (title, created_at, updated_at) VALUES (?, ?, ?) RETURNING *",
    title.trim(),
    now,
    now,
  );
  return task as unknown as Task;
}

/** Removes tasks that have been in the trash longer than the retention period. */
function purgeExpired(db: Database): void {
  const cutoff = new Date(Date.now() - TRASH_RETENTION_DAYS * DAY_MS).toISOString();
  db.all("DELETE FROM tasks WHERE deleted_at IS NOT NULL AND deleted_at < ?", cutoff);
}

/** Deleted tasks that can still be restored, most recently deleted first. */
export function listTrash(db: Database): Task[] {
  purgeExpired(db);
  return db.all(
    "SELECT * FROM tasks WHERE deleted_at IS NOT NULL ORDER BY deleted_at DESC, id DESC",
  ) as unknown as Task[];
}

/** Moves a task to the trash. Idempotent: deleting a trashed task keeps its first deletion time. Returns false when the task does not exist. */
export function deleteTask(db: Database, id: number): boolean {
  purgeExpired(db);
  const rows = db.all(
    "UPDATE tasks SET deleted_at = COALESCE(deleted_at, ?) WHERE id = ? RETURNING id",
    new Date().toISOString(),
    id,
  );
  return rows.length > 0;
}

/** Brings a trashed task back. Idempotent for live tasks. Returns undefined when the task does not exist or was purged. */
export function restoreTask(db: Database, id: number): Task | undefined {
  purgeExpired(db);
  const [task] = db.all("UPDATE tasks SET deleted_at = NULL WHERE id = ? RETURNING *", id);
  return task as unknown as Task | undefined;
}
